-- Reception cannot read a UUID over the phone, and the clinic's paper files
-- carry their own numbers. Two identifiers, as Click4Appointment had:
--
--   patient_code  generated by us, never reused, printed on the file label
--   manual_id     the clinic's own number, optional, unique when present
--
-- Everyone who came from Click4Appointment already has a clinic number — it
-- is the id their export was keyed by — so it is filled in rather than being
-- re-keyed from the register by hand.
BEGIN;

CREATE SEQUENCE patient_code_seq;
ALTER TABLE patients ADD COLUMN patient_code TEXT;
ALTER TABLE patients ADD COLUMN manual_id TEXT;

-- Existing patients are numbered in the order they were registered, so the
-- codes read in the same order as the register book.
WITH ordered AS (SELECT id, row_number() OVER (ORDER BY created_at, id) AS rn FROM patients)
UPDATE patients p SET patient_code = 'SB' || lpad(o.rn::text, 5, '0') FROM ordered o WHERE o.id = p.id;
SELECT setval('patient_code_seq', GREATEST((SELECT count(*) FROM patients), 1));

UPDATE patients SET manual_id = substring(import_key FROM 'click4appointment:id:(.*)$')
 WHERE import_key LIKE 'click4appointment:id:%';

ALTER TABLE patients ALTER COLUMN patient_code SET DEFAULT 'SB' || lpad(nextval('patient_code_seq')::text, 5, '0');
ALTER TABLE patients ALTER COLUMN patient_code SET NOT NULL;

CREATE UNIQUE INDEX patients_patient_code_unique ON patients(patient_code);
-- Optional, but no two patients may share one: a duplicate clinic number is
-- exactly the mix-up this is meant to prevent.
CREATE UNIQUE INDEX patients_manual_id_unique ON patients(manual_id) WHERE manual_id IS NOT NULL;

COMMENT ON COLUMN patients.patient_code IS 'Generated clinic-wide identifier, never reused.';
COMMENT ON COLUMN patients.manual_id IS 'The clinic''s own file number, from the paper register or Click4Appointment.';

COMMIT;
